"use client";

import * as React from "react";
import { Check, ChevronDown } from "lucide-react";
import { Button } from "@repo/design-system/components/ui/button";
import { Chip } from "@repo/design-system/components/ui/chip";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@repo/design-system/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@repo/design-system/components/ui/popover";
import { cn } from "@repo/design-system/lib/utils";

export type MultiSelectOption = {
  label: string;
  value: string;
  keywords?: string[];
};

type MultiSelectPopoverProps = {
  value: string[];
  options: MultiSelectOption[];
  onChange?: (next: string[]) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  className?: string;
  contentClassName?: string;
  disabled?: boolean;
};

function MultiSelectPopover({
  value,
  options,
  onChange,
  placeholder = "Select options",
  searchPlaceholder = "Search options...",
  emptyText = "No options found.",
  className,
  contentClassName,
  disabled = false,
}: MultiSelectPopoverProps) {
  const [open, setOpen] = React.useState(false);

  const selectedLabels = React.useMemo(() => {
    const selected = new Set(value);
    return options
      .filter((option) => selected.has(option.value))
      .map((option) => option.label);
  }, [options, value]);

  const handleToggle = React.useCallback(
    (optionValue: string) => {
      if (!onChange) {
        return;
      }

      const next = value.includes(optionValue)
        ? value.filter((item) => item !== optionValue)
        : [...value, optionValue];
      onChange(next);
    },
    [onChange, value]
  );

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button
          aria-expanded={open}
          className={cn(
            "h-auto min-h-9 w-full justify-between gap-2 px-3 py-2 text-left font-normal",
            className
          )}
          disabled={disabled}
          role="combobox"
          variant="outline"
        >
          <span className="min-w-0 flex-1">
            {selectedLabels.length > 0 ? (
              <span className="flex flex-wrap gap-1">
                {selectedLabels.slice(0, 2).map((label) => (
                  <Chip key={label} size="sm" variant="accent">
                    {label}
                  </Chip>
                ))}
                {selectedLabels.length > 2 ? (
                  <Chip size="sm" variant="muted">
                    +{selectedLabels.length - 2}
                  </Chip>
                ) : null}
              </span>
            ) : (
              <span className="text-muted-foreground">{placeholder}</span>
            )}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className={cn("w-[280px] p-0", contentClassName)}
      >
        <Command>
          <CommandInput placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>{emptyText}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const selected = value.includes(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    keywords={option.keywords}
                    onSelect={() => handleToggle(option.value)}
                    value={`${option.label} ${option.value}`}
                  >
                    <Check
                      className={cn(
                        "mr-2 size-4",
                        selected ? "opacity-100" : "opacity-0"
                      )}
                    />
                    <span className="truncate">{option.label}</span>
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export { MultiSelectPopover };
export type { MultiSelectPopoverProps };
